"""Implementation of lla shortcut management commands."""
import os, re, sys
from pathlib import Path

HELP = """executable-shortcut 
Manage command shortcuts

USAGE:
    executable shortcut [SUBCOMMAND]

OPTIONS:
    -h, --help    Print this message

SUBCOMMANDS:
    add       Add a new shortcut
    create    Interactively create a new shortcut
    export    Export shortcuts to a file
    help      Print this message or the help of the given subcommand(s)
    import    Import shortcuts from a file
    list      List all shortcuts
    remove    Remove a shortcut
"""

def _path():
    return Path(os.environ.get("XDG_CONFIG_HOME", str(Path.home()/".config"))) / "lla" / "config.toml"

def _items(txt):
    out=[]
    for m in re.finditer(r'^([^\s#][^=\r\n]*)\s*=\s*\{\s*plugin_name\s*=\s*"((?:\\.|[^"])*)"\s*,\s*action\s*=\s*"((?:\\.|[^"])*)"\s*,\s*description\s*=\s*"((?:\\.|[^"])*)"\s*\}',txt,re.M):
        out.append((m.group(1).strip().strip('"'), *(s.replace('\\"','"').replace('\\\\','\\') for s in m.groups()[1:])))
    return out

def _write(items):
    p=_path(); p.parent.mkdir(parents=True,exist_ok=True)
    txt=p.read_text() if p.exists() else ""
    txt=re.sub(r'(?ms)^\[shortcuts\]\s*\n.*?(?=^\[|\Z)', '', txt)
    if txt and not txt.endswith('\n'): txt+='\n'
    txt+='\n[shortcuts]\n'
    for n,pl,ac,de in items:
        esc=lambda s:s.replace('\\','\\\\').replace('"','\\"')
        txt+=f'{n}={{ plugin_name = "{esc(pl)}", action = "{esc(ac)}", description = "{esc(de)}"}}\n'
    p.write_text(txt)

def run(argv):
    if not argv or argv[0] != 'shortcut': return False
    a=argv[1:]
    if not a or a[0] in ('-h','--help','help'):
        print(HELP,end=''); return True
    cmd=a[0]
    p=_path()
    txt=p.read_text() if p.exists() else ''
    items=_items(txt)
    if cmd=='list':
        if not items: print('No shortcuts configured')
        else:
            print('Configured Shortcuts:\n')
            for n,pl,ac,de in items:
                print(f'{n} → {pl} {ac}')
                if de: print(f'  Description: {de}')
        return True
    if cmd=='add':
        if any(x in ('-h','--help') for x in a):
            print('executable-shortcut-add \nAdd a new shortcut\n\nUSAGE:\n    executable shortcut add [OPTIONS] <name> <plugin> <action>\n\nARGS:\n    <name>      Name of the shortcut\n    <plugin>    Plugin name\n    <action>    Plugin action\n\nOPTIONS:\n    -d, --description <description>    Optional description of the shortcut\n    -h, --help                         Print help information\n'); return True
        desc=''; vals=[]; i=1
        while i<len(a):
            if a[i] in ('-d','--description') and i+1<len(a): desc=a[i+1]; i+=2
            else: vals.append(a[i]); i+=1
        if len(vals)<3: print('error: the following required arguments were not provided: <name> <plugin> <action>'); return True
        name,plugin,action=vals[:3]
        items=[x for x in items if x[0]!=name]+[(name,plugin,action,desc)]
        _write(items)
        print(f"✓ Added shortcut '{name}' -> {plugin} {action}")
        if desc: print(f'  Description: {desc}')
        return True
    if cmd=='remove':
        if not a[1:]: print('error: the following required arguments were not provided: <name>'); return True
        name=a[1]; new=[x for x in items if x[0]!=name]
        if len(items)==len(new): print(f"✗ Shortcut '{name}' not found")
        else: _write(new); print(f"✓ Removed shortcut '{name}'")
        return True
    if cmd=='export':
        if any(x in ('-h','--help') for x in a):
            print('executable-shortcut-export \nExport shortcuts to a file\n\nUSAGE:\n    executable shortcut export [output]\n\nARGS:\n    <output>    Output file path (defaults to stdout)\n\nOPTIONS:\n    -h, --help    Print help information\n'); return True
        body=''.join(f'[shortcuts.{n}]\nplugin_name = "{pl}"\naction = "{ac}"\ndescription = "{de}"\n\n' for n,pl,ac,de in items)+'[plugin_aliases]\n'
        if len(a)>1:
            Path(a[1]).write_text(body)
        else: print(body,end='')
        return True
    if cmd=='import':
        if any(x in ('-h','--help') for x in a):
            print('executable-shortcut-import \nImport shortcuts from a file\n\nUSAGE:\n    executable shortcut import [OPTIONS] <file>\n\nARGS:\n    <file>    File path to import from\n\nOPTIONS:\n    -h, --help     Print help information\n        --merge    Merge with existing shortcuts (skip conflicts)\n'); return True
        if len(a)<2:
            print('error: the following required arguments were not provided: <file>'); return True
        try: source=Path(a[-1]).read_text()
        except OSError as e:
            print(f"\n✗ Error\n\n  Failed to read file '{a[-1]}': {e}\n"); return True
        imported=[]
        for m in re.finditer(r'(?ms)^\[shortcuts\.([^]\r\n]+)\]\s*\n(.*?)(?=^\[|\Z)',source):
            data=m.group(2)
            def val(key):
                q=re.search(r'(?m)^'+key+r'\s*=\s*"((?:\\.|[^"])*)"',data)
                return q.group(1) if q else ''
            imported.append((m.group(1),val('plugin_name'),val('action'),val('description')))
        if '--merge' in a: imported=items+[x for x in imported if x[0] not in {i[0] for i in items}]
        _write(imported)
        print(f'✓ Imported {len(imported)} shortcut(s)')
        return True
    print(HELP,end=''); return True
"""Small implementation of lla's non-interactive theme install command."""
import os
import shutil
import sys
import re
from pathlib import Path


def install(path: str) -> int:
    source = Path(path).expanduser()
    if not source.exists():
        print(f"\n✗ Error\n\n  Path does not exist: {path}\n")
        return 1
    if source.is_file():
        if source.suffix != ".toml":
            print("\n✗ Error\n\n  Theme file must have .toml extension\n")
            return 1
        files = [source]
    elif source.is_dir():
        files = [p for p in source.iterdir() if p.is_file() and p.suffix == ".toml"]
    else:
        files = []
    if not files:
        print("No themes were installed")
        return 0
    dest = Path.home() / ".config" / "lla" / "themes"
    dest.mkdir(parents=True, exist_ok=True)
    for file in files:
        shutil.copy2(file, dest / file.name)
        print(f"✓ Installed theme: {file.name}")
    print(f"\n{len(files)} theme(s) installed successfully!\nUse lla theme to select a theme")
    return 0


def preview(name: str) -> int:
    roots = [Path.home() / ".config" / "lla" / "themes"]
    candidates = []
    for root in roots:
        candidates.extend([root / (name + ".toml"), root / name])
    theme_path = next((p for p in candidates if p.is_file()), None)
    data = {}
    if theme_path:
        try:
            raw = theme_path.read_text(encoding="utf-8")
            for key in ("name", "author", "description"):
                match = re.search(r"(?m)^\s*" + key + r"\s*=\s*\"((?:[^\"\\]|\\.)*)\"", raw)
                if match:
                    data[key] = bytes(match.group(1), "utf-8").decode("unicode_escape")
        except Exception:
            data = {}
    if not theme_path:
        print(f"\n✗ Error\n\n  Theme '{name}' not found. Install it with `lla theme pull` or place it in ~/.config/lla/themes\n")
        return 1
    title = data.get("name") or name
    author = data.get("author") or "Unknown"
    notes = data.get("description") or "No description"
    print(f"\nTheme preview: {title}\nAuthor : {author}\nNotes  : {notes}\n\nCore palette\n Files       Dirs        Symlinks    Exec        Size        Date       \n\nSample directory listing\nDefault view (lla)\n   src/\n   Cargo.toml\n   scripts/build.sh\n   current -> releases/2025\n   .env\n\nLong view (lla -l)\nPermissions  Size Modified     User Group Name\ndrwxr-xr-x   4.0K Nov 15 10:22 mona staff  src/\n-rw-r--r--   2.4K Nov 14 18:02 mona staff  Cargo.toml\n-rwxr-xr-x   8.8K Nov 13 09:10 mona staff  scripts/build.sh\nlrwxrwxrwx     9B Nov 12 08:01 mona staff  current -> releases/2025\n-rw-r--r--   640B Nov 11 21:58 mona staff  .env\n\nSample search output\nrg --search \"theme\"\nsrc/main.rs:42     let theme = load_theme(name)?;\n         ^^^^\n1 match across 1 file\n")
    return 0


def run(args):
    if len(args) >= 2 and args[0] == "theme" and args[1] == "install":
        if len(args) < 3:
            print("error: The following required arguments were not provided:\n    <path>")
            return 2
        return install(args[2])
    if len(args) >= 3 and args[0] == "theme" and args[1] == "preview":
        return preview(args[2])
    return None


if __name__ == "__main__":
    sys.exit(install(sys.argv[1]))
"""Sorting helpers for lla listing records.

The reference's ordinary name sort compares names case-insensitively and
compares digit runs numerically.  This module accepts either dictionaries
(the JSON record shape) or objects exposing the same attributes.
"""
import re


def _get(item, key, default=None):
    return item.get(key, default) if isinstance(item, dict) else getattr(item, key, default)


def natural_key(value, case_sensitive=False):
    value = str(value)
    if not case_sensitive:
        value = value.casefold()
    return tuple((1, int(part)) if part.isdigit() else (0, part)
                 for part in re.split(r"(\d+)", value))


def sort_records(records, criterion="name", reverse=False, dirs_first=False,
                 case_sensitive=False, natural=True):
    """Return a sorted copy of records using name, size, or date ordering.

    `reverse` applies to the complete ordering, including the directory-first
    grouping, matching the CLI behavior.
    """
    key_name = lambda x: natural_key(_get(x, "name", ""), case_sensitive) if natural else (
        str(_get(x, "name", "")) if case_sensitive else str(_get(x, "name", "")).casefold())
    if criterion == "size":
        key = lambda x: (_get(x, "size_bytes", _get(x, "size", 0)) or 0, key_name(x))
    elif criterion == "date":
        key = lambda x: (_get(x, "modified", _get(x, "modified_time", 0)) or 0, key_name(x))
    else:
        key = key_name
    result = list(records)
    # Size and date listings are newest/largest first by default; name is
    # ascending.  The reverse switch flips that criterion's direction.
    descending = criterion in ("size", "date")
    effective_reverse = bool(reverse) ^ descending
    if dirs_first:
        result.sort(key=lambda x: (_get(x, "file_type", "") not in ("dir", "directory"), key(x)),
                    reverse=bool(reverse))
        # Keep directory grouping stable while applying the per-criterion
        # direction to names within each group.
        result.sort(key=lambda x: key(x), reverse=effective_reverse)
        result.sort(key=lambda x: _get(x, "file_type", "") not in ("dir", "directory"),
                    reverse=bool(reverse))
    else:
        result.sort(key=key, reverse=effective_reverse)
    return result

